import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import process from "node:process";

const repoRoot = process.cwd();
const workspaceRoots = ["bounded-contexts", "contracts", "infrastructure", "packages", "deployables"];
const tsconfigBasePath = path.join(repoRoot, "tsconfig.base.json");
const generatedRegistryComment =
  "// Generated by scripts/sync-workspace-metadata.mjs. Do not edit by hand.\n";
const legacyPlatformRuntimeRegistryPaths = [
  path.join(repoRoot, "infrastructure", "platform-runtime", "api-context-registry.generated.ts"),
  path.join(repoRoot, "infrastructure", "platform-runtime", "web-context-registry.generated.ts"),
];
const generatedRegistryOutputs = [
  {
    kind: "api",
    hostName: "platform-api",
    outputPath: path.join(
      repoRoot,
      "deployables",
      "platform-api",
      "src",
      "generated",
      "api-context-registry.ts",
    ),
  },
  {
    kind: "web",
    hostName: "admin-web",
    outputPath: path.join(
      repoRoot,
      "deployables",
      "admin-web",
      "app",
      "generated",
      "web-context-registry.ts",
    ),
  },
  {
    kind: "web",
    hostName: "marketplace-web",
    outputPath: path.join(
      repoRoot,
      "deployables",
      "marketplace",
      "app",
      "generated",
      "web-context-registry.ts",
    ),
  },
];

function readJson(filePath) {
  return JSON.parse(readFileSync(filePath, "utf8"));
}

function sortObjectKeys(value) {
  return Object.fromEntries(
    Object.entries(value).sort(([left], [right]) => left.localeCompare(right)),
  );
}

function normalizeRelative(filePath) {
  return `./${path.relative(repoRoot, filePath).replaceAll("\\", "/")}`;
}

function normalizeImportPath(fromFile, toFile) {
  const relativePath = path.relative(path.dirname(fromFile), toFile).replaceAll("\\", "/");
  return relativePath.startsWith(".") ? relativePath : `./${relativePath}`;
}

function listWorkspacePackages() {
  const workspaces = [];

  for (const workspaceRoot of workspaceRoots) {
    const rootPath = path.join(repoRoot, workspaceRoot);

    for (const entry of readDir(rootPath)) {
      if (!entry.isDirectory()) {
        continue;
      }

      const packageDir = path.join(rootPath, entry.name);
      const packageJsonPath = path.join(packageDir, "package.json");

      try {
        const packageJson = readJson(packageJsonPath);
        workspaces.push({
          name: packageJson.name,
          dir: packageDir,
          dirName: entry.name,
          root: workspaceRoot,
          packageJson,
        });
      } catch {
        // Ignore directories that are not workspace packages.
      }
    }
  }

  return workspaces.sort((left, right) => left.name.localeCompare(right.name));
}

function readDir(rootPath) {
  return existsSync(rootPath) ? readdirSync(rootPath, { withFileTypes: true }) : [];
}

function toExportsObject(exportsField) {
  if (typeof exportsField === "string") {
    return { ".": exportsField };
  }

  return exportsField ?? {};
}

function buildTsconfigPaths(workspaces) {
  const aliases = {};

  for (const workspace of workspaces) {
    const exportsField = toExportsObject(workspace.packageJson.exports);

    for (const [exportKey, exportTarget] of Object.entries(exportsField)) {
      if (typeof exportTarget !== "string") {
        continue;
      }

      const targetPath = normalizeRelative(
        path.join(workspace.dir, exportTarget.replace(/^\.\//, "")),
      );

      if (exportKey === ".") {
        aliases[workspace.name] = [targetPath];
        continue;
      }

      const exportSuffix = exportKey.replace(/^\.\//, "");
      aliases[`${workspace.name}/${exportSuffix}`] = [targetPath];
    }
  }

  return sortObjectKeys(aliases);
}

function listBoundedContexts(workspaces) {
  return workspaces
    .filter((workspace) => workspace.root === "bounded-contexts")
    .map((workspace) => {
      const manifestPath = path.join(workspace.dir, "context.json");
      const manifest = readJson(manifestPath);

      return {
        contextName: manifest.contextName,
        dirName: workspace.dirName,
        packageName: workspace.name,
        manifest,
        manifestPath,
      };
    })
    .sort((left, right) => left.contextName.localeCompare(right.contextName));
}

function buildApiRegistry(outputPath, hostName, contexts) {
  const activeContexts = contexts.filter((context) =>
    context.manifest.apiDeployables?.includes(hostName),
  );
  const contextImports = activeContexts.map(
    (context) =>
      `import { contextManifest as ${context.contextName}Manifest, module as ${context.contextName}Module } from "${context.packageName}";`,
  );
  const entries = activeContexts.map(
    (context) => `  {
    contextName: "${context.contextName}",
    packageName: "${context.packageName}",
    manifest: ${context.contextName}Manifest,
    module: ${context.contextName}Module,
  },`,
  );

  return `${generatedRegistryComment}
${contextImports.join("\n")}

export const apiContextRegistry = [
${entries.join("\n")}
] as const;
`;
}

function contributesToWebHost(context, hostName) {
  return (
    context.manifest.deployableContributions?.some(
      (contribution) => contribution.deployable === hostName,
    ) ||
    context.manifest.shellContributions?.some(
      (contribution) => contribution.deployable === hostName,
    )
  );
}

function buildWebRegistry(outputPath, hostName, contexts) {
  const activeContexts = contexts.filter((context) => contributesToWebHost(context, hostName));
  const manifestImports = activeContexts.map(
    (context) =>
      `import ${context.contextName}Manifest from "${context.packageName}/context";`,
  );
  const entries = activeContexts.map(
    (context) => `  {
    contextName: "${context.contextName}",
    packageName: "${context.packageName}",
    manifest: ${context.contextName}Manifest as WebContextRegistry[number]["manifest"],
  },`,
  );

  return `${generatedRegistryComment}
import type { WebContextRegistry } from "@chase-sets/platform-runtime/web";

${manifestImports.join("\n")}

export const webContextRegistry = [
${entries.join("\n")}
] as const satisfies WebContextRegistry;
`;
}

function writeFileEnsured(filePath, content) {
  mkdirSync(path.dirname(filePath), { recursive: true });
  writeFileSync(filePath, content, "utf8");
}

function syncTsconfigBase(workspaces) {
  const current = readJson(tsconfigBasePath);
  current.compilerOptions.paths = buildTsconfigPaths(workspaces);
  writeFileSync(tsconfigBasePath, `${JSON.stringify(current, null, 2)}\n`, "utf8");
}

function syncDeployableRegistries(workspaces) {
  const contexts = listBoundedContexts(workspaces);

  for (const output of generatedRegistryOutputs) {
    const content =
      output.kind === "api"
        ? buildApiRegistry(output.outputPath, output.hostName, contexts)
        : buildWebRegistry(output.outputPath, output.hostName, contexts);

    writeFileEnsured(output.outputPath, content);
  }

  for (const legacyPath of legacyPlatformRuntimeRegistryPaths) {
    if (existsSync(legacyPath)) {
      rmSync(legacyPath);
    }
  }
}

function main() {
  const workspaces = listWorkspacePackages();
  syncTsconfigBase(workspaces);
  syncDeployableRegistries(workspaces);
  console.log("Workspace metadata synchronized.");
}

main();
